CREATE DATABASE IF NOT EXISTS bora_pra_obra CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE bora_pra_obra;
CREATE TABLE usuarios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nome VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,senha_hash VARCHAR(255) NOT NULL,ativo TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE temporadas(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ordem INT NOT NULL,nome VARCHAR(160) NOT NULL,faixa_capitulos VARCHAR(40),objetivo TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE episodios(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,numero INT NOT NULL UNIQUE,titulo VARCHAR(255) NOT NULL,data_gravacao DATE NULL,qtd_arquivos INT NOT NULL DEFAULT 0,temporada_id INT UNSIGNED NULL,etapa VARCHAR(160) NULL,status ENUM('Catalogado','Em edição','Pronto','Agendado','Publicado') NOT NULL DEFAULT 'Catalogado',drive_url VARCHAR(500) NULL,youtube_url VARCHAR(500) NULL,data_publicacao DATETIME NULL,observacoes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_ep_temp FOREIGN KEY(temporada_id) REFERENCES temporadas(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE ideias(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,titulo VARCHAR(255) NOT NULL,descricao TEXT,status ENUM('Nova','Em análise','Aprovada','Descartada') NOT NULL DEFAULT 'Nova',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
